parameters.jsCode:
const body = $input.first().json.body || {};
const title = body.title || '🚨 THÔNG BÁO VẬN HÀNH TMS';
const message = body.message || 'Có cập nhật mới từ hệ thống điều phối.';
const orderCode = body.orderCode ? `📦 <b>Mã đơn:</b> <code>${body.orderCode}</code>\n` : '';
const tripCode = body.tripCode ? `🚚 <b>Chuyến xe:</b> <code>${body.tripCode}</code>\n` : '';
const hub = body.hub ? `🏢 <b>Bưu cục / Hub:</b> ${body.hub}\n` : '';
const time = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });

const formattedText = `<b>${title}</b>\n\n${message}\n\n${orderCode}${tripCode}${hub}⏰ <i>Thời gian: ${time}</i>`;

return [{
  json: {
    chat_id: body.chat_id || '-5509877448',
    text: formattedText,
    parse_mode: 'HTML'
  }
}];

